mapper.select:
        select
        orderDetail.*,
        orders.order_no,
        dish.dish_name,
        dish.dish_img
        from order_detail orderDetail
        left join orders orders on orderDetail.order_id = orders.id
		left join dish dish on orderDetail.dish_id = dish.id

            and orderDetail.id = #{id}
            and orderDetail.order_id = #{orderId}
            and orderDetail.dish_id = #{dishId}
            and orderDetail.dish_price = #{dishPrice}
            and orderDetail.num = #{num}
            and orderDetail.create_time = #{createTime}
            and orders.order_no = #{orderNo}
            and dish.dish_name like concat('%',#{dishName},'%')
            and dish.dish_img = #{dishImg}


            limit #{current},#{pageSize}

        select count(*) from order_detail orderDetail
        left join orders orders on orderDetail.order_id = orders.id
		left join dish dish on orderDetail.dish_id = dish.id

            and orderDetail.id = #{id}
